from datetime import datetime

# Ensure we have spotify_token from prior step
assert 'spotify_token' in globals() and spotify_token

def fetch_all_song_library(token):
    song_ids=set()
    page_index=0
    while True:
        page=apis.spotify.show_song_library(access_token=token, page_index=page_index, page_limit=20)
        # Expect 'song_ids' may not exist; schema includes song_id/title
        if not page or page=={}:
            break
        results=page.get('success') or page.get('songs') or page.get('data') or page.get('items')
        if results is None:
            # maybe page itself is list
            if isinstance(page,list):
                results=page
            else:
                # no success wrapper
                results=page.get('results')
        if not results:
            break
        for r in results:
            sid=r.get('song_id')
            if sid is not None:
                song_ids.add(int(sid))
        # termination: if less than page_limit
        if len(results)<20:
            # could still have more if server misreports; but rely on empty next page
            pass
        page_index+=1
        if page_index>1000:
            break
    return song_ids

