            return None
        # try common formats
        for fmt in ["%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M:%S.%f", "%Y-%m-%d"]:
            try:
                return datetime.strptime(ss, fmt)
            except Exception:
                pass
        # last resort: fromisoformat
        try:
            return datetime.fromisoformat(ss)
        except Exception:
            return None
    return None

